import assert from 'node:assert/strict';
import test from 'node:test';
import { createLayer, sectorsOverlap } from './model.js';
import { cuesFromSegments } from './timing.js';
import {
  generationWindows,
  mergeGeneratedMessages,
  placeGenerated,
  stampManual,
  targetMessageCount,
} from './chat.js';

test('un mensaje bloqueado sobrevive a la regeneración de su tramo', () => {
  const manual = stampManual({ t: 12, username: 'ana', text: 'esto queda', color: '#60a5fa' });
  const outside = { ...stampManual({ t: 40, username: 'leo', text: 'afuera' }), locked: false, source: 'generated' as const };
  const incoming = placeGenerated(
    [{ t: 5, username: 'kai', text: 'nuevo' }, { username: 'nio', text: 'otro' }],
    0,
    30,
    [manual.t],
    null,
  );
  const merged = mergeGeneratedMessages([manual, outside], incoming, 0, 30);
  assert.equal(merged.some((message) => message.id === manual.id && message.locked), true);
  assert.equal(merged.some((message) => message.text === 'afuera'), true);
  assert.equal(merged.some((message) => message.text === 'nuevo'), true);
  assert.equal(merged.every((message) => message.t >= 0), true);
});

test('sin sectores el video entero usa el ratio de la capa', () => {
  const layer = createLayer('chat', { ratePerMinute: 10, instruction: 'fans' });
  const windows = generationWindows(120, layer.chat!);
  assert.equal(windows.length, 1);
  assert.equal(windows[0]?.start, 0);
  assert.equal(windows[0]?.end, 120);
  assert.equal(windows[0]?.ratePerMinute, 10);
  assert.equal(targetMessageCount(10, 0, 120), 20);
});

test('un sector parte el video y conserva su instrucción', () => {
  const layer = createLayer('chat');
  layer.chat!.instruction = 'general';
  layer.chat!.sectors = [{
    id: crypto.randomUUID(),
    name: 'Clímax',
    start: 30,
    end: 50,
    instruction: 'más ácido',
    ratePerMinute: 30,
  }];
  const windows = generationWindows(60, layer.chat!);
  assert.deepEqual(windows.map((window) => [window.start, window.end, window.instruction]), [
    [0, 30, 'general'],
    [30, 50, 'más ácido'],
    [50, 60, 'general'],
  ]);
  const only = generationWindows(60, layer.chat!, layer.chat!.sectors[0]!.id);
  assert.equal(only.length, 1);
  assert.equal(only[0]?.instruction, 'más ácido');
});

test('los sectores superpuestos se rechazan', () => {
  const existing = [{
    id: crypto.randomUUID(),
    name: 'A',
    start: 0,
    end: 20,
    instruction: '',
    ratePerMinute: 8,
  }];
  assert.equal(sectorsOverlap(existing, { start: 10, end: 30 }, 60), true);
  assert.equal(sectorsOverlap(existing, { start: 20, end: 30 }, 60), false);
});

test('los subtítulos largos se parten en cues de hasta ocho palabras', () => {
  const cues = cuesFromSegments([{ start: 0, end: 4, text: 'uno dos tres cuatro cinco seis siete ocho nueve diez' }]);
  assert.equal(cues.length, 2);
  assert.equal(cues[0]?.text.split(' ').length, 8);
  assert.equal(cues[1]?.text, 'nueve diez');
  assert.ok(cues[1]!.start >= cues[0]!.start);
});

import { chatColor, newId, round3, type ChatData, type ChatSector, type TimedMessage } from './model.js';

export type GenerationWindow = {
  start: number;
  end: number;
  ratePerMinute: number;
  instruction: string;
  sectorId: string | null;
};

export function resolvedEnd(sector: ChatSector, duration: number): number {
  if (sector.end == null) return duration;
  return Math.min(sector.end, duration);
}

export function generationWindows(duration: number, chat: ChatData, sectorId?: string): GenerationWindow[] {
  if (sectorId) {
    const sector = chat.sectors.find((item) => item.id === sectorId);
    if (!sector) throw new Error('No existe ese sector.');
    const start = Math.max(0, Math.min(sector.start, duration));
    const end = Math.max(start, Math.min(resolvedEnd(sector, duration), duration));
    return [{
      start,
      end,
      ratePerMinute: sector.ratePerMinute,
      instruction: sector.instruction || chat.instruction,
      sectorId: sector.id,
    }];
  }

  const sectors = [...chat.sectors].sort((a, b) => a.start - b.start);
  const windows: GenerationWindow[] = [];
  let cursor = 0;
  for (const sector of sectors) {
    const start = Math.max(0, Math.min(sector.start, duration));
    const end = Math.max(start, Math.min(resolvedEnd(sector, duration), duration));
    if (start > cursor + 0.05) {
      windows.push({
        start: cursor,
        end: start,
        ratePerMinute: chat.defaultRatePerMinute,
        instruction: chat.instruction,
        sectorId: null,
      });
    }
    if (end > start + 0.05) {
      windows.push({
        start,
        end,
        ratePerMinute: sector.ratePerMinute,
        instruction: sector.instruction || chat.instruction,
        sectorId: sector.id,
      });
    }
    cursor = Math.max(cursor, end);
  }
  if (duration - cursor > 0.05) {
    windows.push({
      start: cursor,
      end: duration,
      ratePerMinute: chat.defaultRatePerMinute,
      instruction: chat.instruction,
      sectorId: null,
    });
  }
  return windows;
}

export function targetMessageCount(ratePerMinute: number, start: number, end: number): number {
  const minutes = Math.max(0, end - start) / 60;
  if (minutes <= 0) return 0;
  return Math.max(1, Math.round(ratePerMinute * minutes));
}

export type CountedWindow = GenerationWindow & { count: number };

export function chunkWindow(window: GenerationWindow, count: number, chunkSize = 40): CountedWindow[] {
  if (count <= chunkSize) return [{ ...window, count }];
  const parts = Math.ceil(count / chunkSize);
  const span = window.end - window.start;
  const chunks: CountedWindow[] = [];
  for (let index = 0; index < parts; index += 1) {
    const size = index === parts - 1 ? count - chunkSize * (parts - 1) : chunkSize;
    chunks.push({
      ...window,
      start: window.start + span * (index / parts),
      end: window.start + span * ((index + 1) / parts),
      count: size,
    });
  }
  return chunks;
}

export type GeneratedDraft = { t?: number; username?: string; text?: string; color?: string };

export function placeGenerated(
  raw: GeneratedDraft[],
  start: number,
  end: number,
  lockedTimes: number[],
  sectorId: string | null,
): TimedMessage[] {
  const span = Math.max(0.2, end - start);
  const cleaned = raw
    .map((item) => ({
      username: String(item.username ?? '').trim().slice(0, 40),
      text: String(item.text ?? '').trim().slice(0, 300),
      color: item.color,
      t: Number(item.t),
    }))
    .filter((item) => item.username && item.text);

  const inside = cleaned.map((item) => item.t).filter((time) => Number.isFinite(time) && time >= start && time <= end);
  const sorted = [...inside].sort((a, b) => a - b);
  const spread = sorted.length >= 2 ? sorted[sorted.length - 1]! - sorted[0]! : 0;
  const useModelTimes = inside.length === cleaned.length && spread >= span * 0.45;

  return cleaned.map((item, index) => {
    let time = useModelTimes ? item.t : start + span * ((index + 0.5) / cleaned.length);
    time = Math.min(end, Math.max(start, time));
    for (const locked of lockedTimes) {
      if (Math.abs(time - locked) < 0.35) time = Math.min(end, Math.max(start, locked + 0.45));
    }
    return {
      id: newId(),
      t: round3(time),
      username: item.username,
      text: item.text,
      color: chatColor(index, item.color),
      sectorId,
      locked: false,
      source: 'generated' as const,
    };
  }).sort((a, b) => a.t - b.t);
}

export function mergeGeneratedMessages(existing: TimedMessage[], incoming: TimedMessage[], start: number, end: number): TimedMessage[] {
  const kept = existing.filter((message) => message.locked || message.t < start - 0.001 || message.t > end + 0.001);
  return [...kept, ...incoming].sort((a, b) => a.t - b.t || a.username.localeCompare(b.username));
}

export function stampManual(input: { t: number; username: string; text: string; color?: string }, index = 0): TimedMessage {
  return {
    id: newId(),
    t: round3(Math.max(0, input.t)),
    username: input.username.trim().slice(0, 40),
    text: input.text.trim().slice(0, 300),
    color: chatColor(index, input.color),
    sectorId: null,
    locked: true,
    source: 'manual',
  };
}

export * from './model.js';
export * from './timing.js';
export * from './chat.js';

import { z } from 'zod';

export const LAYER_TYPES = [
  'live-badge',
  'chat',
  'alert',
  'lower-third',
  'watermark',
  'qr',
  'lut',
  'subtitle',
] as const;

export const LAYER_ANIMATIONS = ['none', 'blink', 'pulse', 'fade-in', 'slide-in', 'spin'] as const;
export const layerAnimationSchema = z.enum(LAYER_ANIMATIONS);

export const assetKindSchema = z.enum(['image', 'video', 'audio']);
export const assetSchema = z.object({
  file: z.string().min(1).max(240),
  mimeType: z.string().min(1).max(120),
  name: z.string().min(1).max(160).default('Sin nombre'),
  kind: assetKindSchema.default('image'),
});
export type Asset = z.infer<typeof assetSchema>;

export const layerTypeSchema = z.enum(LAYER_TYPES);
export type LayerType = z.infer<typeof layerTypeSchema>;

export const CHAT_COLORS = [
  '#60a5fa',
  '#f472b6',
  '#34d399',
  '#fbbf24',
  '#a78bfa',
  '#f87171',
  '#2dd4bf',
  '#fb7185',
] as const;

export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

export function newId(): string {
  return crypto.randomUUID();
}

const hexColor = z.string().regex(/^#[0-9a-fA-F]{6}$/);

export const timedMessageSchema = z.object({
  id: z.string().uuid(),
  t: z.number().min(0),
  username: z.string().min(1).max(40),
  text: z.string().min(1).max(300),
  color: hexColor,
  sectorId: z.string().uuid().nullable(),
  locked: z.boolean(),
  source: z.enum(['manual', 'generated']),
});
